import{_ as e,o as l,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const x=JSON.parse('{"title":"지원 파일 관리자 및 대화상자 연동","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/file-manager-support.md","filePath":"ko-KR/user-guide/file-manager-support.md","lastUpdated":1787586465000}'),n={name:"ko-KR/user-guide/file-manager-support.md"};function d(s,t,i,o,g,f){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="지원-파일-관리자-및-대화상자-연동" tabindex="-1">지원 파일 관리자 및 대화상자 연동 <a class="header-anchor" href="#지원-파일-관리자-및-대화상자-연동" aria-label="Permalink to &quot;지원 파일 관리자 및 대화상자 연동&quot;">​</a></h1><p>Lertaro는 단순한 독립형 실행기를 넘어, Windows 파일 탐색기, 서드파티 파일 관리자 및 각종 소프트웨어 대화상자에 깊숙이 내장되어 파일 열기, 저장 및 디렉토리 이동 효율을 극대화합니다.</p><h2 id="_1-3대-핵심-연동-기능" tabindex="-1">1. 3대 핵심 연동 기능 <a class="header-anchor" href="#_1-3대-핵심-연동-기능" aria-label="Permalink to &quot;1. 3대 핵심 연동 기능&quot;">​</a></h2><p>대상 창의 특성에 따라 최대 세 가지 연동 기능이 제공됩니다.</p><ul><li><strong>인라인 검색 (Inline Search)</strong>: 대상 창 상단이나 파일 대화상자 내부에 초고속 검색창이 직접 임베드되어 현재 작업 창을 벗어나지 않고 검색 수행.</li><li><strong>퀵 내비게이션 (Quick Navigation)</strong>: 빈 공간을 휠클릭(또는 좌클릭 더블클릭)하거나 임베드된 로고를 클릭하여 열린 폴더, 즐겨찾기, 최근 기록 및 사용자 지정 폴더의 계단식 메뉴 호출.</li><li><strong>활성 경로 감지 (Active Path Detection)</strong>: 대상 창에서 현재 열려 있는 실제 디렉토리를 실시간으로 감지하여 검색 범위를 해당 폴더로 자동 제한하거나 상대 경로 동작 수행.</li></ul><h2 id="_2-시스템-기본-컴포넌트-지원-기본-탑재" tabindex="-1">2. 시스템 기본 컴포넌트 지원 (기본 탑재) <a class="header-anchor" href="#_2-시스템-기본-컴포넌트-지원-기본-탑재" aria-label="Permalink to &quot;2. 시스템 기본 컴포넌트 지원 (기본 탑재)&quot;">​</a></h2><p>별도의 플러그인 설치 없이 Lertaro 코어 엔진에서 기본 지원합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">대상 창 유형</th><th style="text-align:left;">인라인 검색</th><th style="text-align:left;">퀵 내비게이션 호출 방식</th><th style="text-align:left;">활성 경로 감지</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows 파일 탐색기</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">빈 공간 더블클릭 또는 휠클릭</td><td style="text-align:left;">지원</td></tr><tr><td style="text-align:left;"><strong>모던 열기/저장 파일 대화상자</strong></td><td style="text-align:left;">지원 (대화상자 내 직접 임베드)</td><td style="text-align:left;">휠클릭 또는 임베드된 로고 좌클릭</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>클래식 열기/저장 파일 대화상자</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 임베드된 로고 좌클릭</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>클래식 폴더 찾아보기 대화상자</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 임베드된 로고 좌클릭</td><td style="text-align:left;">—</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>파일 선택 대화상자의 경우 Lertaro가 창 내부에 직접 내장되어 있어 별도의 외부 경로 감지가 필요하지 않습니다. 퀵 내비게이션에서 항목을 클릭하면 대화상자가 해당 폴더로 안전하게 이동합니다.</p></div><h2 id="_3-전문-서드파티-파일-관리자-지원-선택-플러그인" tabindex="-1">3. 전문 서드파티 파일 관리자 지원 (선택 플러그인) <a class="header-anchor" href="#_3-전문-서드파티-파일-관리자-지원-선택-플러그인" aria-label="Permalink to &quot;3. 전문 서드파티 파일 관리자 지원 (선택 플러그인)&quot;">​</a></h2><p>파워 유저를 위한 인기 파일 관리자 전용 플러그인을 제공합니다. <a href="./settings/plugins.html"><strong>설정 → 플러그인</strong></a>에서 활성화하고 인라인 검색과 퀵 내비게이션을 개별 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">파일 관리자</th><th style="text-align:left;">인라인 검색</th><th style="text-align:left;">퀵 내비게이션 호출 방식</th><th style="text-align:left;">활성 경로 감지</th><th style="text-align:left;">핵심 통신 기술</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Directory Opus</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">파일 목록 영역에서 휠클릭</td><td style="text-align:left;">지원</td><td style="text-align:left;"><code>WM_COPYDATA</code> 공식 원격 제어 API</td></tr><tr><td style="text-align:left;"><strong>Total Commander</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">파일 목록 영역에서 휠클릭</td><td style="text-align:left;">지원</td><td style="text-align:left;"><code>WM_COPYDATA</code> 메시지 프로토콜</td></tr><tr><td style="text-align:left;"><strong>XYplorer</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">파일 목록 영역에서 휠클릭</td><td style="text-align:left;">지원</td><td style="text-align:left;">전용 프로세스 통신</td></tr><tr><td style="text-align:left;"><strong>Files</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">파일 목록 영역에서 휠클릭</td><td style="text-align:left;">지원</td><td style="text-align:left;">Windows UI Automation 프레임워크</td></tr><tr><td style="text-align:left;"><strong>One Commander</strong></td><td style="text-align:left;">지원</td><td style="text-align:left;">파일 목록 영역에서 휠클릭</td><td style="text-align:left;">지원</td><td style="text-align:left;">Windows UI Automation 프레임워크</td></tr></tbody></table><h3 id="directory-opus-전용-심층-연동" tabindex="-1">Directory Opus 전용 심층 연동 <a class="header-anchor" href="#directory-opus-전용-심층-연동" aria-label="Permalink to &quot;Directory Opus 전용 심층 연동&quot;">​</a></h3><ul><li><strong>재귀 폴더 크기 열 (Lertaro 크기)</strong>: Directory Opus 플러그인에서 &quot;Lertaro 크기 열 활성화&quot;를 켜면 커스텀 스크립트 열이 설치됩니다. Lertaro의 인메모리 인덱스에서 폴더 크기를 직접 읽어오므로 <strong>디스크 I/O가 전혀 없이</strong> 드라이브 전체 폴더 용량을 즉시 확인할 수 있습니다.</li><li><strong>영구 서식 저장</strong>: Directory Opus 열 선택기에서 &quot;Lertaro 크기&quot;를 추가한 후 <strong>폴더 → 폴더 서식 → 저장 → 모든 폴더에 서식 저장</strong>을 클릭합니다.</li></ul><h3 id="everything-호환-서비스-ipc" tabindex="-1">Everything 호환 서비스 (IPC) <a class="header-anchor" href="#everything-호환-서비스-ipc" aria-label="Permalink to &quot;Everything 호환 서비스 (IPC)&quot;">​</a></h3><p><a href="./settings/general.html#시스템"><strong>설정 → 일반 → 시스템</strong></a>에서 <strong>Everything 호환 서비스 (IPC) 활성화</strong>를 켜면 표준 Everything Win32 IPC 인터페이스를 에뮬레이트합니다. Directory Opus, Total Commander, Flow Launcher 등에서 Everything 없이도 Lertaro 인덱스를 직접 활용할 수 있습니다.</p><h2 id="_4-자체-제작-대화상자-소프트웨어-지원-전용-플러그인" tabindex="-1">4. 자체 제작 대화상자 소프트웨어 지원 (전용 플러그인) <a class="header-anchor" href="#_4-자체-제작-대화상자-소프트웨어-지원-전용-플러그인" aria-label="Permalink to &quot;4. 자체 제작 대화상자 소프트웨어 지원 (전용 플러그인)&quot;">​</a></h2><p>표준 Windows 대화상자를 쓰지 않는 주요 소프트웨어를 위한 전용 플러그인을 제공합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">소프트웨어 및 대화상자 유형</th><th style="text-align:left;">인라인 검색</th><th style="text-align:left;">퀵 내비게이션 호출 방식</th><th style="text-align:left;">연동 설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>WPS Office</strong> 열기/저장 대화상자</td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 로고 클릭</td><td style="text-align:left;">WPS Writer, Spreadsheets, Presentation, PDF 지원</td></tr><tr><td style="text-align:left;"><strong>WinRAR</strong> 압축 해제 대화상자</td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 로고 클릭</td><td style="text-align:left;">압축 해제 대상 폴더 빠른 지정</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> 압축 해제 대화상자</td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 로고 클릭</td><td style="text-align:left;">해제 대상 폴더 즉시 선택</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> 파일 추가 대화상자</td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 로고 클릭</td><td style="text-align:left;">압축할 소스 파일 빠른 선택</td></tr><tr><td style="text-align:left;"><strong>AutoCAD</strong> 열기/저장 대화상자</td><td style="text-align:left;">지원</td><td style="text-align:left;">휠클릭 또는 로고 클릭</td><td style="text-align:left;">CAD 도면 파일의 신속한 저장 및 호출에 최적화</td></tr></tbody></table><p>각 플러그인은 컨트롤 계층 구조와 핸들을 직접 감지하여 동작하므로 다국어 언어팩이나 테마 변경에 영향을 받지 않습니다.</p>',20)])])}const h=e(n,[["render",d]]);export{x as __pageData,h as default};
